const V={bg:"#FAF8F5",surface:"#FFFFFF",ink:"#15140F",ink2:"#43413A",muted:"#8A877E",line:"#E8E4DC",line2:"#F0ECE4",accent:"#B8553D",accentSoft:"#F5E7E2",pos:"#4F7A3F",posSoft:"#E8EFE2",warn:"#B07B23",warnSoft:"#F5ECD8",neg:"#A03826",negSoft:"#F5DDD7",blue:"#2A3D5C",blueSoft:"#DEE6F0"};
const MONO="'JetBrains Mono',ui-monospace,monospace";
const BODY="'Inter',system-ui,sans-serif";
const DISP="'Inter Tight','Inter',system-ui,sans-serif";
const crd={background:V.surface,border:"1px solid "+V.line,borderRadius:8};

function Badge({label,color,bg}){return <span style={{fontSize:11.5,padding:"2px 8px",borderRadius:999,fontWeight:500,background:bg||(color+"18"),color:color,whiteSpace:"nowrap"}}>{label}</span>;}
function KPI({label,value,sub,subColor}){return<div style={{...crd,padding:"16px 20px",flex:"1 1 150px",minWidth:140}}><div style={{fontSize:12,color:V.muted,fontWeight:500,marginBottom:8}}>{label}</div><div style={{fontFamily:DISP,fontWeight:600,fontSize:26,letterSpacing:"-.03em",color:V.ink,lineHeight:1.1}}>{value}</div>{sub&&<div style={{fontSize:12,color:subColor||V.muted,fontWeight:500,marginTop:6}}>{sub}</div>}</div>;}
function Pill({children,active,onClick,badge}){return<button onClick={onClick} style={{padding:"8px 14px",borderRadius:999,border:active?0:"1px solid "+V.line,cursor:"pointer",fontSize:13,fontWeight:500,fontFamily:BODY,background:active?V.ink:V.surface,color:active?V.bg:V.ink2,display:"flex",alignItems:"center",gap:6}}>{children}{badge&&<span style={{fontSize:10.5,background:active?"rgba(255,255,255,.2)":V.negSoft,color:active?"#fff":V.neg,padding:"1px 6px",borderRadius:999,fontWeight:600}}>{badge}</span>}</button>;}

function Dashboard(){
  return <div>
    <div style={{display:"flex",gap:12,flexWrap:"wrap",marginBottom:24}}>
      <KPI label="Réf. totales" value={STATS.totalRefs.toLocaleString()} sub={STATS.refsActives.toLocaleString()+" actives"}/>
      <KPI label="En promo" value={STATS.refsEnPromo.toLocaleString()} sub="5 497 manuelles"/>
      <KPI label="Marge moyenne" value={STATS.margeMoyenne+"%"} sub={STATS.alerteMargeNeg+" marges négatives"} subColor={V.neg}/>
      <KPI label="Opés Trade" value={PROMOS.filter(function(p){return p.act;}).length} sub={PROMOS.length+" total 2026"} subColor={V.warn}/>
    </div>
    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:16,marginBottom:24}}>
      <div style={{...crd,padding:20}}>
        <div style={{fontFamily:DISP,fontWeight:600,fontSize:14,marginBottom:16}}>Alertes critiques</div>
        {[{s:"high",m:STATS.alerteMargeNeg+" réfs à marge négative"},{s:"high",m:STATS.alerteStockZero.toLocaleString()+" réfs actives stock 0"},{s:"high",m:STATS.refsSansAllergenes.toLocaleString()+" sans allergènes (66%)"},{s:"medium",m:STATS.refsSansMarque.toLocaleString()+" sans marque (57%)"},{s:"medium",m:STATS.refsNonCategorisees.toLocaleString()+" non catégorisées"}].map(function(a,i){
          return <div key={i} style={{display:"flex",alignItems:"flex-start",gap:10,padding:"10px 12px",background:a.s==="high"?V.negSoft:V.line2,borderRadius:6,marginBottom:6}}>
            <span style={{width:6,height:6,borderRadius:"50%",background:a.s==="high"?V.neg:V.warn,marginTop:6,flexShrink:0}}/>
            <span style={{fontSize:13,color:V.ink,lineHeight:1.45}}>{a.m}</span></div>;})}
      </div>
      <div style={{...crd,padding:20}}>
        <div style={{fontFamily:DISP,fontWeight:600,fontSize:14,marginBottom:16}}>Top 10 ventes (CA 7j)</div>
        {VENTES.slice(0,10).map(function(v,i){return <div key={i} style={{display:"flex",alignItems:"center",gap:10,padding:"5px 0",borderBottom:i<9?"1px solid "+V.line2:"none"}}>
          <span style={{width:18,height:18,borderRadius:18,display:"flex",alignItems:"center",justifyContent:"center",background:i<3?V.accentSoft:V.line2,color:i<3?V.accent:V.muted,fontWeight:600,fontSize:9.5,flexShrink:0}}>{i+1}</span>
          <span style={{flex:1,fontSize:12,color:V.ink,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{v.n}</span>
          <span style={{fontFamily:MONO,fontSize:11,color:V.ink,fontWeight:500}}>{v.c7}</span>
          <span style={{fontFamily:MONO,fontSize:11,color:V.pos}}>{v.mp}</span>
        </div>;})}
      </div>
    </div>
    <div style={{...crd,padding:20}}>
      <div style={{fontFamily:DISP,fontWeight:600,fontSize:14,marginBottom:16}}>Top fournisseurs</div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:4}}>
        {TOP_FOURN.map(function(f,i){return <div key={i} style={{display:"flex",alignItems:"center",gap:8,padding:"5px 8px",borderRadius:6,background:i<2?V.accentSoft:"transparent"}}>
          <span style={{width:18,height:18,borderRadius:18,display:"flex",alignItems:"center",justifyContent:"center",background:i<3?V.accent:V.line2,color:i<3?"#fff":V.muted,fontWeight:600,fontSize:9,flexShrink:0}}>{i+1}</span>
          <span style={{flex:1,fontSize:12,color:V.ink,fontWeight:i<3?600:400}}>{f.n}</span>
          <span style={{fontFamily:MONO,fontSize:11,color:V.ink2}}>{f.r.toLocaleString()}</span>
        </div>;})}
      </div>
    </div>
  </div>;
}

function OffreTab(){
  var [sub,setSub]=useState("ventes");
  var [search,setSearch]=useState("");
  var [filtre,setFiltre]=useState("all");
  var [page,setPage]=useState(1);
  var PP=50;

  var filteredCat=useMemo(function(){
    return CATALOG.filter(function(p){
      if(search){var s=search.toLowerCase();if(!(p.nom.toLowerCase().includes(s)||String(p.id).includes(s)||p.ean.includes(s)||p.marque.toLowerCase().includes(s)||p.fournisseur.toLowerCase().includes(s)))return false;}
      if(filtre==="promo"&&!p.promo)return false;
      if(filtre==="stock0"&&p.stock>0)return false;
      if(filtre==="noallerg"&&p.allerg)return false;
      if(filtre==="bio"&&!p.bio)return false;
      return true;
    });
  },[search,filtre]);

  var totalP=Math.ceil(filteredCat.length/PP);
  var paged=filteredCat.slice((page-1)*PP,page*PP);

  var filteredVentes=useMemo(function(){
    if(!search)return VENTES;
    var s=search.toLowerCase();
    return VENTES.filter(function(v){return v.n.toLowerCase().includes(s);});
  },[search]);

  return <div>
    <div style={{display:"flex",gap:4,marginBottom:20,background:V.surface,borderRadius:999,padding:4,border:"1px solid "+V.line,width:"fit-content"}}>
      {[{k:"ventes",l:"Top Ventes (CA)"},{k:"catalogue",l:"Catalogue Produits"},{k:"alertes",l:"Alertes"}].map(function(t){
        return <Pill key={t.k} active={sub===t.k} onClick={function(){setSub(t.k);setPage(1);}}>{t.l}</Pill>;})}
    </div>

    {sub==="ventes"&&<div>
      <input value={search} onChange={function(e){setSearch(e.target.value);}} placeholder="Rechercher un produit..."
        style={{width:"100%",maxWidth:400,height:34,padding:"0 12px",borderRadius:8,border:"1px solid "+V.line,background:V.surface,fontSize:13,fontFamily:BODY,color:V.ink,outline:"none",marginBottom:16}}/>
      <div style={{...crd,overflow:"hidden"}}>
        <table style={{width:"100%",borderCollapse:"collapse",fontSize:12.5}}>
          <thead><tr style={{borderBottom:"1px solid "+V.line}}>
            {["#","Produit","PA HT","PV TTC","Marge","CA 7j TTC","CA 30j TTC","Marge 7j HT"].map(function(h){
              return <th key={h} style={{padding:"10px 10px",textAlign:"left",color:V.muted,fontSize:11,fontWeight:500,textTransform:"uppercase",background:V.bg,position:"sticky",top:0}}>{h}</th>;})}
          </tr></thead>
          <tbody>{filteredVentes.map(function(v,i){
            return <tr key={i} style={{borderBottom:"1px solid "+V.line2}}
              onMouseEnter={function(e){e.currentTarget.style.background="rgba(0,0,0,.015)";}}
              onMouseLeave={function(e){e.currentTarget.style.background="transparent";}}>
              <td style={{padding:"8px 10px",fontFamily:MONO,fontSize:11,color:V.muted}}>{i+1}</td>
              <td style={{padding:"8px 10px",color:V.ink,fontWeight:500,maxWidth:250,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{v.n}</td>
              <td style={{padding:"8px 10px",fontFamily:MONO,fontSize:12}}>{v.pa}</td>
              <td style={{padding:"8px 10px",fontFamily:MONO,fontSize:12}}>{v.pv}</td>
              <td style={{padding:"8px 10px",fontFamily:MONO,fontSize:12,color:V.pos,fontWeight:600}}>{v.mp}</td>
              <td style={{padding:"8px 10px",fontFamily:MONO,fontSize:12,fontWeight:600}}>{v.c7}</td>
              <td style={{padding:"8px 10px",fontFamily:MONO,fontSize:12}}>{v.c30}</td>
              <td style={{padding:"8px 10px",fontFamily:MONO,fontSize:12,color:V.pos}}>{v.m7}</td>
            </tr>;})}
          </tbody>
        </table>
      </div>
    </div>}

    {sub==="catalogue"&&<div>
      <div style={{display:"flex",gap:8,marginBottom:16,flexWrap:"wrap"}}>
        <input value={search} onChange={function(e){setSearch(e.target.value);setPage(1);}} placeholder="Rechercher ID, EAN, nom, marque, fournisseur..."
          style={{flex:"1 1 240px",height:34,padding:"0 12px",borderRadius:8,border:"1px solid "+V.line,background:V.surface,fontSize:13,fontFamily:BODY,color:V.ink,outline:"none"}}/>
        {[{k:"all",l:"Tout"},{k:"promo",l:"En promo"},{k:"stock0",l:"Stock 0"},{k:"noallerg",l:"Sans allergènes"},{k:"bio",l:"Bio"}].map(function(f){
          return <button key={f.k} onClick={function(){setFiltre(f.k);setPage(1);}}
            style={{padding:"5px 10px",borderRadius:999,border:"1px solid "+(filtre===f.k?V.ink:V.line),background:filtre===f.k?V.ink:V.surface,color:filtre===f.k?V.bg:V.ink2,fontSize:12,fontWeight:500,cursor:"pointer"}}>{f.l}</button>;})}
      </div>
      <div style={{display:"flex",justifyContent:"space-between",marginBottom:10}}>
        <span style={{fontSize:12,color:V.muted}}>{filteredCat.length} produits — page {page}/{totalP||1}</span>
        <div style={{display:"flex",gap:4}}>
          <button onClick={function(){setPage(Math.max(1,page-1));}} disabled={page===1} style={{padding:"4px 10px",borderRadius:6,border:"1px solid "+V.line,background:V.surface,color:page===1?V.line:V.ink,cursor:page===1?"default":"pointer",fontSize:12}}>←</button>
          <button onClick={function(){setPage(Math.min(totalP,page+1));}} disabled={page>=totalP} style={{padding:"4px 10px",borderRadius:6,border:"1px solid "+V.line,background:V.surface,color:page>=totalP?V.line:V.ink,cursor:page>=totalP?"default":"pointer",fontSize:12}}>→</button>
        </div>
      </div>
      <div style={{...crd,overflow:"hidden"}}>
        <table style={{width:"100%",borderCollapse:"collapse",fontSize:12.5}}>
          <thead><tr style={{borderBottom:"1px solid "+V.line}}>
            {["ID","EAN","Produit","Marque","Fournisseur","PA","PV","Marge","Stock","Bio","Allerg.","Promo"].map(function(h){
              return <th key={h} style={{padding:"10px 8px",textAlign:"left",color:V.muted,fontSize:11,fontWeight:500,textTransform:"uppercase",background:V.bg,position:"sticky",top:0}}>{h}</th>;})}
          </tr></thead>
          <tbody>{paged.map(function(p){
            var mc=p.marge<0?V.neg:p.marge<15?V.warn:p.marge<25?V.ink2:V.pos;
            var sc=p.stock===0?V.neg:p.stock<5?V.warn:V.pos;
            return <tr key={p.id} style={{borderBottom:"1px solid "+V.line2}}
              onMouseEnter={function(e){e.currentTarget.style.background="rgba(0,0,0,.015)";}}
              onMouseLeave={function(e){e.currentTarget.style.background="transparent";}}>
              <td style={{padding:"8px 8px",fontFamily:MONO,fontSize:11,color:V.accent,fontWeight:600}}>{p.id}</td>
              <td style={{padding:"8px 8px",fontFamily:MONO,fontSize:10,color:V.muted}}>{p.ean||"—"}</td>
              <td style={{padding:"8px 8px",color:V.ink,fontWeight:500,maxWidth:200,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{p.nom}</td>
              <td style={{padding:"8px 8px",color:p.marque?V.ink2:V.line,fontSize:12}}>{p.marque||"—"}</td>
              <td style={{padding:"8px 8px",color:V.ink2,fontSize:12}}>{p.fournisseur||"—"}</td>
              <td style={{padding:"8px 8px",fontFamily:MONO,fontSize:12}}>{p.pa.toFixed(2)}€</td>
              <td style={{padding:"8px 8px",fontFamily:MONO,fontSize:12}}>{p.pv.toFixed(2)}€</td>
              <td style={{padding:"8px 8px",fontFamily:MONO,fontSize:12,color:mc,fontWeight:600}}>{p.marge.toFixed(1)}%</td>
              <td style={{padding:"8px 8px",fontFamily:MONO,fontSize:12,color:sc,fontWeight:600}}>{p.stock}</td>
              <td style={{padding:"8px 8px"}}>{p.bio?<Badge label="Bio" color={V.pos} bg={V.posSoft}/>:""}</td>
              <td style={{padding:"8px 8px"}}>{p.allerg?<span style={{color:V.pos}}>✓</span>:<span style={{color:V.neg,fontWeight:600}}>✕</span>}</td>
              <td style={{padding:"8px 8px"}}>{p.promo?<Badge label="Promo" color={V.accent} bg={V.accentSoft}/>:""}</td>
            </tr>;})}
          </tbody>
        </table>
      </div>
    </div>}

    {sub==="alertes"&&<div>
      <div style={{display:"flex",gap:14,flexWrap:"wrap",marginBottom:24}}>
        <KPI label="Marges négatives" value={STATS.alerteMargeNeg} subColor={V.neg}/>
        <KPI label="Stock 0 (actives)" value={STATS.alerteStockZero.toLocaleString()} subColor={V.neg}/>
        <KPI label="Sans allergènes" value={STATS.refsSansAllergenes.toLocaleString()} sub="66% du catalogue" subColor={V.warn}/>
        <KPI label="Non catégorisées" value={STATS.refsNonCategorisees.toLocaleString()} subColor={V.warn}/>
      </div>
      <div style={{...crd,padding:20}}>
        <div style={{fontFamily:DISP,fontWeight:600,fontSize:14,marginBottom:16}}>Produits à marge négative (erreurs probables PA/PV)</div>
        {CATALOG.filter(function(p){return p.marge<0;}).slice(0,10).map(function(p,i){
          return <div key={i} style={{display:"flex",alignItems:"center",gap:12,padding:"10px 0",borderBottom:i<9?"1px solid "+V.line2:"none"}}>
            <span style={{fontFamily:MONO,fontSize:11,color:V.accent,fontWeight:600,width:50}}>{p.id}</span>
            <span style={{flex:1,fontSize:13,color:V.ink}}>{p.nom}</span>
            <span style={{fontFamily:MONO,fontSize:12}}>PA {p.pa.toFixed(2)}€</span>
            <span style={{fontFamily:MONO,fontSize:12}}>PV {p.pv.toFixed(2)}€</span>
            <Badge label={p.marge.toFixed(1)+"%"} color={V.neg} bg={V.negSoft}/>
          </div>;})}
      </div>
    </div>}
  </div>;
}

function TradeMK(){
  var [sub,setSub]=useState("planning");
  var [promos,setPromos]=useState(PROMOS);
  var [showForm,setShowForm]=useState(false);
  var [newOp,setNewOp]=useState({m:"",t:"",d:"",f:"",cat:"",cmd:false,act:false,caA:null,caO:null,ev:"",roi:"",fb:"",cm:""});
  var moisOrder=["Janvier","Fevrier","Mars","Avril","Mai","Juin","Juillet","Aout","Septembre","Octobre","Novembre","Décembre"];

  function addOp(){setPromos([...promos,{...newOp,i:promos.length}]);setShowForm(false);setNewOp({m:"",t:"",d:"",f:"",cat:"",cmd:false,act:false,caA:null,caO:null,ev:"",roi:"",fb:"",cm:""});}

  return <div>
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20}}>
      <div style={{display:"flex",gap:4,background:V.surface,borderRadius:999,padding:4,border:"1px solid "+V.line}}>
        {[{k:"planning",l:"Planning"},{k:"performance",l:"Performance"},{k:"calendrier",l:"Calendrier"}].map(function(t){return <Pill key={t.k} active={sub===t.k} onClick={function(){setSub(t.k);}}>{t.l}</Pill>;})}
      </div>
      <button onClick={function(){setShowForm(true);}} style={{height:34,padding:"0 16px",borderRadius:8,border:0,background:V.accent,color:"#fff",fontSize:13,fontWeight:500,cursor:"pointer",fontFamily:BODY}}>+ Nouvelle opé</button>
    </div>

    {sub==="planning"&&<div>
      <div style={{display:"flex",gap:12,flexWrap:"wrap",marginBottom:24}}>
        <KPI label="Actives" value={promos.filter(function(p){return p.act;}).length}/>
        <KPI label="Total 2026" value={promos.length}/>
        <KPI label="Avec résultats" value={promos.filter(function(p){return p.caO;}).length}/>
      </div>
      {moisOrder.map(function(mois){var ops=promos.filter(function(p){return p.m===mois;});if(!ops.length)return null;
        return <div key={mois} style={{marginBottom:24}}>
          <div style={{fontFamily:DISP,fontWeight:600,fontSize:15,marginBottom:10}}>{mois} <Badge label={ops.length+" opé"+(ops.length>1?"s":"")} color={V.muted}/></div>
          {ops.map(function(op,j){var hasData=op.caO!==null;var roiC=!op.roi?"":parseFloat(op.roi)>=3?V.pos:parseFloat(op.roi)>=1.5?V.warn:V.neg;
            return <div key={j} style={{...crd,padding:"16px 20px",marginBottom:8,borderLeft:op.act?"3px solid "+V.pos:op.d?"3px solid "+V.warn:"3px solid "+V.line}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}>
                <div style={{flex:1}}>
                  <div style={{fontSize:13.5,fontWeight:600,color:V.ink,lineHeight:1.4}}>{op.t}</div>
                  <div style={{display:"flex",gap:8,marginTop:6,flexWrap:"wrap"}}>
                    {op.cat&&<Badge label={op.cat} color={V.blue}/>}
                    {op.d&&<span style={{fontSize:11.5,color:V.muted}}>{op.d} → {op.f}</span>}
                    {op.act&&<Badge label="Active" color={V.pos} bg={V.posSoft}/>}
                    {!op.act&&op.d&&<Badge label="Terminée" color={V.muted}/>}
                    {!op.act&&!op.d&&<Badge label="À planifier" color={V.warn} bg={V.warnSoft}/>}
                  </div>
                </div>
                {hasData&&<div style={{display:"flex",gap:16,flexShrink:0}}>
                  {op.ev&&<div style={{textAlign:"center"}}><div style={{fontSize:10,color:V.muted}}>Évol.</div><div style={{fontFamily:MONO,fontSize:13,fontWeight:600,color:V.pos}}>{op.ev}</div></div>}
                  {op.roi&&<div style={{textAlign:"center"}}><div style={{fontSize:10,color:V.muted}}>ROI</div><div style={{fontFamily:MONO,fontSize:13,fontWeight:600,color:roiC}}>{op.roi}x</div></div>}
                </div>}
              </div>
              {hasData&&<div style={{display:"flex",gap:20,fontSize:12,color:V.ink2,marginTop:6}}>
                <span>CA avant: <strong style={{fontFamily:MONO}}>{op.caA?op.caA.toFixed(0)+"€":"—"}</strong></span>
                <span>CA opé: <strong style={{fontFamily:MONO,color:V.pos}}>{op.caO.toFixed(0)}€</strong></span>
              </div>}
              {op.fb&&<div style={{fontSize:12,color:V.muted,marginTop:6,fontStyle:"italic"}}>💬 {op.fb}</div>}
            </div>;})}
        </div>;})}
    </div>}

    {sub==="performance"&&<div style={{...crd,overflow:"hidden"}}>
      <table style={{width:"100%",borderCollapse:"collapse",fontSize:12.5}}>
        <thead><tr style={{borderBottom:"1px solid "+V.line}}>
          {["Opération","Catégorie","CA avant","CA opé","Évol.","ROI","Statut"].map(function(h){
            return <th key={h} style={{padding:"10px 10px",textAlign:"left",color:V.muted,fontSize:11,fontWeight:500,textTransform:"uppercase",background:V.bg}}>{h}</th>;})}
        </tr></thead>
        <tbody>{promos.filter(function(p){return p.caO;}).sort(function(a,b){return(b.caO||0)-(a.caO||0);}).map(function(op,i){
          var roiV=parseFloat(op.roi)||0;var roiC=roiV>=3?V.pos:roiV>=1.5?V.warn:V.neg;
          return <tr key={i} style={{borderBottom:"1px solid "+V.line2}}>
            <td style={{padding:"10px",color:V.ink,fontWeight:500,maxWidth:250,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{op.t.slice(0,55)}</td>
            <td style={{padding:"10px"}}>{op.cat&&<Badge label={op.cat} color={V.blue}/>}</td>
            <td style={{padding:"10px",fontFamily:MONO}}>{op.caA?op.caA.toFixed(0)+"€":"—"}</td>
            <td style={{padding:"10px",fontFamily:MONO,fontWeight:600,color:V.pos}}>{op.caO.toFixed(0)}€</td>
            <td style={{padding:"10px",fontFamily:MONO,color:V.pos}}>{op.ev||"—"}</td>
            <td style={{padding:"10px"}}>{op.roi?<Badge label={op.roi+"x"} color={roiC}/>:"—"}</td>
            <td style={{padding:"10px"}}>{op.act?<Badge label="Active" color={V.pos} bg={V.posSoft}/>:<Badge label="Terminée" color={V.muted}/>}</td>
          </tr>;})}
        </tbody>
      </table>
    </div>}

    {sub==="calendrier"&&<div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:12}}>
      {moisOrder.map(function(mois){var ops=promos.filter(function(p){return p.m===mois;});var isBasse=mois==="Juillet"||mois==="Aout";
        return <div key={mois} style={{...crd,padding:"16px 18px",background:isBasse?V.negSoft:V.surface,border:isBasse?"1px solid "+V.neg+"22":"1px solid "+V.line}}>
          <div style={{fontSize:14,fontWeight:600,color:V.ink,marginBottom:6}}>{mois}</div>
          <div style={{fontSize:11,color:V.muted,marginBottom:10,lineHeight:1.4,minHeight:30}}>
            {ops.length>0?ops.map(function(o){return o.cat;}).filter(Boolean).filter(function(v,i,a){return a.indexOf(v)===i;}).join(", ")||"À planifier":isBasse?"Pause estivale":"—"}</div>
          <Badge label={ops.length+" opé"+(ops.length>1?"s":"")} color={ops.length===0?V.neg:ops.length>=3?V.pos:V.warn}/>
        </div>;})}
    </div>}

    {showForm&&<div style={{position:"fixed",top:0,left:0,right:0,bottom:0,background:"rgba(20,18,12,.18)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:200}} onClick={function(){setShowForm(false);}}>
      <div onClick={function(e){e.stopPropagation();}} style={{...crd,width:520,padding:28,boxShadow:"0 4px 24px rgba(20,18,12,.12)"}}>
        <div style={{display:"flex",justifyContent:"space-between",marginBottom:20}}><h3 style={{fontFamily:DISP,fontWeight:600,fontSize:18,margin:0}}>Nouvelle opération</h3><button onClick={function(){setShowForm(false);}} style={{background:"none",border:"none",fontSize:20,color:V.muted,cursor:"pointer"}}>✕</button></div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12,marginBottom:16}}>
          {[{l:"Mois",k:"m"},{l:"Description",k:"t"},{l:"Date début",k:"d"},{l:"Date fin",k:"f"},{l:"Catégorie",k:"cat"},{l:"CA avant promo",k:"caA"}].map(function(field){
            return <div key={field.k}><label style={{fontSize:12,color:V.muted,display:"block",marginBottom:4}}>{field.l}</label>
              <input value={newOp[field.k]||""} onChange={function(e){var u={...newOp};u[field.k]=e.target.value;setNewOp(u);}} style={{width:"100%",height:34,padding:"0 10px",borderRadius:6,border:"1px solid "+V.line,background:V.bg,fontSize:13,fontFamily:BODY,color:V.ink,outline:"none",boxSizing:"border-box"}}/></div>;})}
        </div>
        <div style={{display:"flex",gap:12,marginBottom:16}}>
          <label style={{fontSize:13,color:V.ink2,display:"flex",alignItems:"center",gap:6,cursor:"pointer"}}><input type="checkbox" checked={newOp.cmd} onChange={function(e){setNewOp({...newOp,cmd:e.target.checked});}}/>Commande OK</label>
          <label style={{fontSize:13,color:V.ink2,display:"flex",alignItems:"center",gap:6,cursor:"pointer"}}><input type="checkbox" checked={newOp.act} onChange={function(e){setNewOp({...newOp,act:e.target.checked});}}/>Active</label>
        </div>
        <button onClick={addOp} style={{width:"100%",height:38,borderRadius:8,border:0,background:V.accent,color:"#fff",fontSize:14,fontWeight:500,cursor:"pointer",fontFamily:BODY}}>Ajouter</button>
      </div>
    </div>}
  </div>;
}

function Placeholder({name,items}){
  return <div style={{...crd,display:"grid",placeItems:"center",textAlign:"center",padding:"60px 20px",gap:8,color:V.muted}}>
    <h3 style={{fontFamily:DISP,margin:0,fontWeight:600,color:V.ink,fontSize:16}}>{name}</h3>
    <p style={{margin:0,maxWidth:400,fontSize:13,lineHeight:1.5}}>{items.join(" · ")}</p>
    <span style={{fontSize:12,color:V.accent,background:V.accentSoft,padding:"6px 14px",borderRadius:999,fontWeight:500,marginTop:8}}>Prêt à connecter</span>
  </div>;
}

export default function CockpitLBV(){
  var [tab,setTab]=useState("dashboard");
  var tabs=[{key:"dashboard",label:"Tableau de bord"},{key:"achats",label:"Achats"},{key:"offre",label:"Offre"},{key:"marketing",label:"Marketing"},{key:"trade",label:"Trade MK"},{key:"categ",label:"Categ Mgmt"}];
  var now=new Date();var gr=now.getHours()<12?"Bonjour":now.getHours()<18?"Bon après-midi":"Bonsoir";
  var meta={dashboard:"Accueil",achats:"Achats",offre:"Offre",marketing:"Marketing",trade:"Trade Marketing",categ:"Category Management"};

  return <div style={{fontFamily:BODY,background:V.bg,color:V.ink,minHeight:"100vh",display:"grid",gridTemplateColumns:"220px 1fr",fontSize:14,lineHeight:1.45}}>
    <style>{"@import url('https://fonts.googleapis.com/css2?family=Inter+Tight:wght@400;500;600;700&family=Inter:wght@400;450;500;600;700&family=JetBrains+Mono:wght@400;500;600&display=swap');*{box-sizing:border-box;}::-webkit-scrollbar{width:10px;}::-webkit-scrollbar-thumb{background:"+V.line+";border-radius:10px;border:3px solid "+V.bg+";}"}</style>
    <aside style={{background:V.bg,borderRight:"1px solid "+V.line,display:"flex",flexDirection:"column",padding:"22px 14px 18px",gap:4}}>
      <div style={{display:"flex",alignItems:"center",gap:10,padding:"4px 8px 20px"}}>
        <div style={{width:28,height:28,borderRadius:7,background:V.ink,color:V.bg,display:"grid",placeItems:"center",fontFamily:DISP,fontWeight:600,fontSize:13}}>Lv</div>
        <div style={{fontFamily:DISP,fontWeight:600,fontSize:15}}>La belle <em style={{fontStyle:"italic",fontWeight:400,color:V.muted}}>vie</em></div>
      </div>
      {tabs.map(function(t){var a=tab===t.key;return <button key={t.key} onClick={function(){setTab(t.key);}} style={{display:"flex",alignItems:"center",gap:10,padding:"7px 10px",borderRadius:6,border:0,cursor:"pointer",textAlign:"left",width:"100%",background:a?V.surface:"transparent",color:a?V.ink:V.ink2,fontWeight:a?500:450,fontSize:13.5,fontFamily:BODY,boxShadow:a?"inset 0 0 0 1px "+V.line:"none"}}
        onMouseEnter={function(e){if(!a)e.currentTarget.style.background="rgba(0,0,0,.04)";}}
        onMouseLeave={function(e){if(!a)e.currentTarget.style.background="transparent";}}>{t.label}</button>;})}
      <div style={{flex:1}}/>
      <div style={{paddingTop:12,borderTop:"1px solid "+V.line,display:"flex",alignItems:"center",gap:10}}>
        <div style={{width:28,height:28,borderRadius:"50%",background:V.accentSoft,color:V.accent,display:"grid",placeItems:"center",fontWeight:600,fontSize:11}}>JM</div>
        <div><b style={{fontSize:12.5,fontWeight:500,display:"block"}}>Jess</b><span style={{fontSize:11,color:V.muted}}>Achats / Offre</span></div>
      </div>
    </aside>
    <main style={{display:"flex",flexDirection:"column",overflow:"hidden"}}>
      <header style={{padding:"16px 28px",borderBottom:"1px solid "+V.line}}>
        <h1 style={{fontFamily:DISP,fontWeight:600,fontSize:22,letterSpacing:"-.025em",margin:0}}>{tab==="dashboard"?gr+", Jess":meta[tab]}</h1>
      </header>
      <div style={{overflow:"auto",flex:1}}><div style={{padding:"28px 28px 64px",maxWidth:1400}}>
        {tab==="dashboard"&&<Dashboard/>}
        {tab==="offre"&&<OffreTab/>}
        {tab==="trade"&&<TradeMK/>}
        {tab==="achats"&&<AchatsTab/>}
        {tab==="marketing"&&<MarketingTab/>}
        {tab==="categ"&&<CategTab/>}
      </div></div>
    </main>
  </div>;
}
